base::RepeatingClosure MakeCopyImageAction(
    content::RenderFrameHost& frame, const content::ContextMenuParams& params) {
  if (!params.has_image_contents)
    return {};
  return base::BindRepeating(
      [](const content::WeakDocumentPtr& document, int x, int y) {
        auto* target = document.AsRenderFrameHostIfValid();
        if (target && target->IsActive())
          target->CopyImageAt(x, y);
      },
      frame.GetWeakDocumentPtr(), params.x, params.y);
}

GURL PageMenuImageUrl(const content::ContextMenuParams& params) {
  if (params.media_type != blink::mojom::ContextMenuDataMediaType::kImage)
    return {};
  const auto& url = params.src_url;
  if (!url.is_valid() ||
      !(url.SchemeIsHTTPOrHTTPS() || url.SchemeIs("blob") ||
        url.SchemeIs("data") || url.SchemeIsFile())) {
    return {};
  }
  return url;
}

void WorkspaceShell::BuildLinkMenu(GURL url, std::string source_workspace,
                                   const PageMenuNavigation* page) {
  link_menu_runner_.reset(); link_menu_.reset(); route_menu_.reset();
  extension_page_menus_.clear();
  extension_page_actions_.clear();
  context_url_ = std::move(url); link_source_workspace_ = std::move(source_workspace);
  page_menu_url_ = page ? page->url : GURL();
  page_menu_save_link_ = page ? page->save_link : base::RepeatingClosure();
  page_menu_copy_image_ = page ? page->copy_image : base::RepeatingClosure();
  page_menu_image_url_ = page ? page->image_url : GURL();
  route_workspaces_ = state_.workspaces;
  route_menu_ = std::make_unique<DesignMenuModel>(this);
  link_menu_ = std::make_unique<DesignMenuModel>(this);
  // Design: Page context menu. Back, Forward, Reload and Copy page address
  // share one icon row; a link gets its own section under a header.
  if (page) {
    link_menu_->AddItem(kPageNavigation, {});
    if (context_url_.is_empty() && CleanUrlForCopy(page_menu_url_)) {
      link_menu_->AddItemWithIcon(kCopyCleanPageAddress, T(u"Kopiuj bez trackerów"),
                                  MenuIcon(vector_icons::kLinkIcon));
    }
  }
  const bool image = page_menu_copy_image_ || page_menu_image_url_.is_valid();
  if (image) {
    link_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
    link_menu_->AddTitle(base::i18n::ToUpper(T(u"Obraz")));
    if (IsCommandIdEnabled(kOpenImageInNewTab))
      link_menu_->AddItemWithIcon(kOpenImageInNewTab, T(u"Otwórz obraz w nowej karcie"),
                                  MenuIcon(kMenuNewTabIcon));
    if (page_menu_copy_image_)
      link_menu_->AddItemWithIcon(kCopyImage, T(u"Kopiuj obraz"),
                                  MenuIcon(vector_icons::kContentCopyIcon));
    if (page_menu_image_url_.is_valid())
      link_menu_->AddItemWithIcon(kCopyImageAddress, T(u"Kopiuj adres obrazu"),
                                  MenuIcon(vector_icons::kLinkIcon));
  }
  if (!context_url_.SchemeIsHTTPOrHTTPS()) return;
  if (page) {
    link_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
    std::u16string where = base::UTF8ToUTF16(std::string(context_url_.host()) + std::string(context_url_.path()));
    if (where.ends_with(u"/")) where.pop_back();
    if (where.size() > 34) where = where.substr(0, 33) + u"…";
    link_menu_->AddTitle(base::i18n::ToUpper(T(u"Link")) + u"  " + where);
  }
  for (const auto& entry : sidebar::link_context_menu(LinkMenuStateFor(state_, context_url_, link_source_workspace_, route_workspaces_))) {
    const auto label = base::UTF8ToUTF16(std::string(entry.label));
    switch (entry.kind) {
      case 1: link_menu_->AddSeparator(ui::NORMAL_SEPARATOR); break;
      case 2: link_menu_->AddSubMenuWithIcon(entry.command, label, route_menu_.get(), MenuIcon(kMenuSpacesIcon)); break;
      case 3: route_menu_->AddRadioItem(entry.command, label, 2); break;
      case 5: route_menu_->AddItem(entry.command, label); break;
      case 6: route_menu_->AddSeparator(ui::NORMAL_SEPARATOR); break;
      case 0:
        if (entry.command == kLinkPeek)
          link_menu_->AddItemWithIcon(entry.command, label, MenuIcon(kMenuSidebarIcon));
        else if (entry.command == kLinkNewTab)
          link_menu_->AddItemWithIcon(entry.command,
              image ? T(u"Otwórz link w nowej karcie") : label,
              MenuIcon(kMenuNewTabIcon));
        else if (entry.command == kLinkSplit)
          link_menu_->AddItemWithIcon(entry.command, label, MenuIcon(vector_icons::kOpenInNewFlippableIcon));
        else
          link_menu_->AddItem(entry.command, label);
        break;
    }
  }
  if (page_menu_save_link_)
    link_menu_->AddItemWithIcon(kSaveLink, T(u"Zapisz link jako…"),
                                MenuIcon(vector_icons::kDownloadIcon));
  if (page)
    link_menu_->AddItemWithIcon(kCopyLinkAddress, T(u"Kopiuj adres linku"),
                                MenuIcon(vector_icons::kLinkIcon));
  if (CleanUrlForCopy(context_url_)) {
    link_menu_->AddItemWithIcon(kCopyCleanLinkAddress, T(u"Kopiuj bez trackerów"),
                                MenuIcon(vector_icons::kLinkIcon));
  }
}

void WorkspaceShell::ShowLinkMenu(GURL url, std::string source_workspace,
                                  gfx::Point point, base::RepeatingClosure inspect,
                                  std::optional<PageMenuNavigation> navigation) {
  ShowLinkMenu(std::move(url), std::move(source_workspace), point,
               std::move(inspect), std::move(navigation), false);
}

void WorkspaceShell::ShowLinkMenu(GURL url, std::string source_workspace,
                                  gfx::Point point, base::RepeatingClosure inspect,
                                  std::optional<PageMenuNavigation> navigation, bool from_address) {
  BuildLinkMenu(std::move(url), std::move(source_workspace), navigation ? &*navigation : nullptr);
  if (from_address && callbacks_.site_panel) {
    link_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
    link_menu_->AddItemWithIcon(kAllSiteSettings, T(u"Wszystkie ustawienia witryny"),
                               MenuIcon(vector_icons::kTuneIcon));
  }
  inspect_element_ = std::move(inspect);
  const bool source = navigation && navigation->url.SchemeIsHTTPOrHTTPS();
  if (inspect_element_ || source) link_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
  if (inspect_element_)
    link_menu_->AddItemWithIcon(19010, T(u"Zbadaj element"), MenuIcon(vector_icons::kCodeIcon));
  if (source)
    link_menu_->AddItemWithIcon(kViewSource, T(u"Pokaż źródło strony"), MenuIcon(kMenuSourceIcon));
  if (navigation && !navigation->extension_items.empty()) {
    link_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
    int command = 31000;
    const auto add_item = [&](ui::SimpleMenuModel& model, const PageMenuItem& item) {
      if (item.separator) {
        model.AddSeparator(ui::NORMAL_SEPARATOR);
        return;
      }
      model.AddItem(command, item.title);
      model.SetEnabledAt(model.GetItemCount() - 1, item.enabled);
      if (item.enabled)
        extension_page_actions_.emplace(command, item.run);
      ++command;
    };
    for (const auto& item : navigation->extension_items) {
      if (item.children.empty()) {
        add_item(*link_menu_, item);
        continue;
      }
      auto submenu = std::make_unique<DesignMenuModel>(this);
      for (const auto& child : item.children)
        add_item(*submenu, child);
      link_menu_->AddSubMenu(command++, item.title, submenu.get());
      link_menu_->SetEnabledAt(link_menu_->GetItemCount() - 1, item.enabled);
      extension_page_menus_.push_back(std::move(submenu));
    }
  }
  if (navigation) {
    auto menu = static_cast<DesignMenuModel*>(link_menu_.get())->CreateViewMenu();
    menu->GetSubmenu()->set_minimum_preferred_width(264);
    auto* item = menu->GetMenuItemByID(kPageNavigation);
    // One 32 px icon row instead of a full-height menu item.
    item->set_vertical_margin(2);
    auto* bar = item->AddChildView(std::make_unique<views::View>());
    bar->GetViewAccessibility().SetRole(ax::mojom::Role::kGroup);
    bar->GetViewAccessibility().SetName(T(u"Nawigacja"));
    auto* layout = bar->SetLayoutManager(std::make_unique<views::BoxLayout>(
        views::BoxLayout::Orientation::kHorizontal, gfx::Insets::VH(0, 4), 4));
    const auto add_button = [&](PageCommand command, const gfx::VectorIcon& icon,
                                const std::u16string& name, bool enabled) {
      auto* button = bar->AddChildView(std::make_unique<PageMenuNavigationButton>(
          base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,
                                 base::RepeatingCallback<void(PageCommand)> run,
                                 PageCommand action) {
            if (!shell) return;
            base::SingleThreadTaskRunner::GetCurrentDefault()->PostTask(
                FROM_HERE, base::BindOnce(run, action));
            shell->link_menu_runner_->Cancel();
          }, weak_factory_.GetWeakPtr(), navigation->run, command), icon, name));
      button->SetEnabled(enabled);
      layout->SetFlexForView(button, 1);
    };
    add_button(PageCommand::kBack, vector_icons::kArrowBackIcon, T(u"Wstecz"), navigation->can_go_back);
    add_button(PageCommand::kForward, vector_icons::kArrowForwardIcon, T(u"Dalej"), navigation->can_go_forward);
    add_button(PageCommand::kReload, vector_icons::kReloadCustomIcon, T(u"Odśwież"), navigation->can_reload);
    auto* copy = bar->AddChildView(std::make_unique<PageMenuNavigationButton>(
        base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell) {
          if (!shell) return;
          shell->ExecuteCommand(kCopyPageAddress, 0);
          shell->link_menu_runner_->Cancel();
        }, weak_factory_.GetWeakPtr()), vector_icons::kLinkIcon, T(u"Kopiuj adres strony")));
    copy->SetEnabled(IsWorkspaceTabUrl(page_menu_url_));
    layout->SetFlexForView(copy, 1);
    link_menu_runner_ = std::make_unique<views::MenuRunner>(std::move(menu), kZitterMenuRun);
  } else {
    link_menu_runner_ = std::make_unique<views::MenuRunner>(link_menu_.get(), kZitterMenuRun);
  }
  link_menu_runner_->RunMenuAt(widget_, nullptr, gfx::Rect(point, gfx::Size()), views::MenuAnchorPosition::kTopLeft,
      ui::mojom::MenuSourceType::kMouse, gfx::NativeView(), ZitterMenuCorners());
}

void WorkspaceShell::BuildWorkspaceMenu(std::string id) {
  workspace_menu_runner_.reset();
  workspace_menu_.reset();
  profile_menu_.reset();
  context_tab_.reset();context_tab_identity_={};
  context_pin_.clear();
  context_workspace_id_ = std::move(id);
  menu_profiles_ = state_.profiles;
  profile_menu_ = std::make_unique<DesignMenuModel>(this);
  const auto add_live_folders = [this] {
    const size_t after_icon = workspace_menu_->GetIndexOfCommandId(kEmojiMenu).value() + 1;
    workspace_menu_->InsertItemAt(after_icon, kNewWorkspaceFolder, T(u"Nowy folder"));
    if (!callbacks_.configure_live_folder || callbacks_.github_live_folders_only) return;
    live_folders_menu_ = std::make_unique<DesignMenuModel>(this);
    for (size_t index = 0; index < kLiveFolderProviders.size(); ++index) {
      live_folders_menu_->AddItem(kConfigureWorkspaceLiveFolderBase + index,
                                  std::u16string(kLiveFolderProviderNames[index]) + u"…");
    }
    workspace_menu_->InsertSubMenuAt(after_icon, kLiveFoldersMenu, u"Live Folders",
                                    live_folders_menu_.get());
  };
  if (metal_sidebar_) {
    color_menu_ = std::make_unique<DesignMenuModel>(this);
    emoji_menu_ = std::make_unique<DesignMenuModel>(this);
    workspace_menu_ = std::make_unique<DesignMenuModel>(this);
    const auto entries = sidebar::workspace_context_menu(RustWorkspaceMenuState());
    // Fill submenus first; their headers in the main menu reference them.
    for (uint32_t pass : {1u, 0u}) for (const auto& entry : entries) {
      if ((entry.group == 0) != (pass == 0)) continue;
      auto* model = entry.group == 1 ? profile_menu_.get() : entry.group == 2 ? color_menu_.get() : entry.group == 3 ? emoji_menu_.get() : workspace_menu_.get();
      const auto label = base::UTF8ToUTF16(std::string(entry.label));
      switch (entry.kind) {
        case 1: model->AddSeparator(ui::NORMAL_SEPARATOR); break;
        case 2: model->AddSubMenu(entry.command, label, entry.command == kSetProfile ? profile_menu_.get() : entry.command == kColorMenu ? color_menu_.get() : emoji_menu_.get()); break;
        case 3: model->AddRadioItem(entry.command, label, 1); break;
        case 4: model->AddCheckItem(entry.command, label); break;
        default: model->AddItem(entry.command, label);
      }
    }
    add_live_folders();
    return;
  }
  for (size_t i = 0; i < menu_profiles_.size(); ++i)
    profile_menu_->AddRadioItem(kProfileCommandBase + i, base::UTF8ToUTF16(menu_profiles_[i].name), 1);
  profile_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
  profile_menu_->AddItem(kEditProfile, T(u"Edytuj profile…"));
  profile_menu_->AddItem(kNewProfile, T(u"Dodaj nowy profil…"));
  workspace_menu_ = std::make_unique<DesignMenuModel>(this);
  workspace_menu_->AddSubMenu(kSetProfile, T(u"Profil przeglądania"), profile_menu_.get());
  color_menu_ = std::make_unique<DesignMenuModel>(this);
  const std::array<std::u16string, kWorkspacePresetCount> color_names = {T(u"Fiolet"), T(u"Koral"), T(u"Niebo"), T(u"Bursztyn"), T(u"Róż"), T(u"Mięta"), T(u"Zieleń"), T(u"Grafit")};
  for (size_t i = 0; i < kWorkspacePresetCount; ++i)
    color_menu_->AddCheckItem(kColorBase + i, color_names[i]);
  color_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
  color_menu_->AddItem(kCustomColor, T(u"Własny kolor…"));
  emoji_menu_ = std::make_unique<DesignMenuModel>(this);
  for (size_t i = 0; i < kWorkspaceEmojis.size(); ++i)
    emoji_menu_->AddCheckItem(kEmojiBase + i, kWorkspaceEmojis[i]);
  emoji_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
  emoji_menu_->AddItem(kCustomEmoji, T(u"Własna ikonka…"));
  emoji_menu_->AddCheckItem(kClearEmoji, T(u"Bez ikonki (kropka)"));
  workspace_menu_->AddSubMenu(kColorMenu, T(u"Kolor przestrzeni"), color_menu_.get());
  workspace_menu_->AddSubMenu(kEmojiMenu, T(u"Ikonka przestrzeni"), emoji_menu_.get());
  workspace_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
  workspace_menu_->AddItem(kWorkspaceSettings, T(u"Ustawienia przestrzeni"));
  workspace_menu_->AddSeparator(ui::NORMAL_SEPARATOR);  // The destructive action last.
  workspace_menu_->AddItem(kRemoveWorkspace, T(u"Usuń przestrzeń"));
  add_live_folders();
}

void WorkspaceShell::BuildFolderMenu(std::string parent) {
  context_tab_.reset();context_tab_identity_={};context_pin_.clear();
  workspace_menu_runner_.reset();
  workspace_menu_ = std::make_unique<DesignMenuModel>(this);
  folder_parent_id_ = std::move(parent);
  context_workspace_id_ = state_.workspace_id;
  const auto folder = std::ranges::find(state_.pins, folder_parent_id_, &PinnedItem::id);
  if (folder != state_.pins.end() && folder->live_folder) {
    const auto& config = *folder->live_folder;
    const bool github = config.provider == LiveFolderProvider::kGitHub;
    workspace_menu_->AddItem(kConfigureLiveFolder, github ? T(u"Ustawienia folderu GitHub…")
                                                          : T(u"Ustawienia folderu Live…"));
    if (!github || !config.account.empty() || !config.filter.empty())
      workspace_menu_->AddItem(kRefreshLiveFolder, github ? T(u"Odśwież PR-y")
                                                         : T(u"Odśwież folder"));
    workspace_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
    workspace_menu_->AddItem(kDeleteFolder, T(u"Usuń folder"));
    return;
  }
  if (metal_sidebar_) {
    for (const auto& entry : sidebar::folder_context_menu(RustFolderMenuState())) {
      if (entry.command == 0) workspace_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
      else workspace_menu_->AddItem(entry.command, base::UTF8ToUTF16(std::string(entry.label)));
    }
    return;
  }
  workspace_menu_->AddItem(kNewFolder, folder_parent_id_.empty() ? T(u"Nowy folder…") : T(u"Nowy podfolder…"));
  if (!folder_parent_id_.empty()) {
    workspace_menu_->AddSeparator(ui::NORMAL_SEPARATOR);
    workspace_menu_->AddItem(kRenameFolder, T(u"Zmień nazwę…"));
    workspace_menu_->AddItem(kDeleteFolder, T(u"Usuń folder"));
  }
}

