void WorkspaceShell::RefreshFormViewports(){
  auto refresh=[&](auto&& self,views::View* view)->void{
    if(auto* paragraph=views::AsViewClass<SceneParagraph>(view))paragraph->OnVisibleBoundsChanged();
    if(auto* row=views::AsViewClass<AppearanceRow>(view))row->SyncViewport();
    for(const auto& child:view->children())self(self,child.get());};
  for(auto* root:{settings_root_.get(),import_root_.get()})if(root){RefreshChoiceViewports(root);refresh(refresh,root);root->SchedulePaint();}
}
void WorkspaceShell::RefreshPreferenceViewport(){
  SchedulePreferenceChrome();
  if(preferences_body_)RefreshChoiceViewports(preferences_body_);
  for(const auto& [key,field]:preference_textfields_)field->view()->SchedulePaint();
  if(site_origin_)site_origin_->view()->SchedulePaint();
}
void WorkspaceShell::BuildRustPreferenceRows(const sidebar::PreferenceCatalogue& catalogue) {
  using Kind=sidebar::PreferenceRowKind;
  using Action=sidebar::PreferenceActionKind;
  auto weak=weak_factory_.GetWeakPtr();
  auto text=[](const rust::String& value){return base::UTF8ToUTF16(std::string(value));};
  auto strings=[&](const auto& input){std::vector<std::u16string> output;for(const auto& value:input)output.push_back(text(value));return output;};
  auto copy=[&](views::View* parent,std::u16string value,SkColor tone,int delta,gfx::Font::Weight weight,bool multiline){return AddPreferenceCopy(parent,std::move(value),tone,delta,static_cast<int>(weight),multiline);};
  // Assistant permissions and safeguards share a card each, under one heading.
  auto group_of=[](const sidebar::PreferenceSpec& spec)->int{
    if (spec.kind == Kind::Updates || spec.kind == Kind::AutoUpdateCheck ||
        spec.kind == Kind::AutoUpdateDownload) return 2;
    const std::string key(spec.key);
    for(const char* k:{"assistant_tabs","assistant_pages","assistant_actions","assistant_history","assistant_web"})if(key==k)return 0;
    for(const char* k:{"assistant_confirm_clicks","assistant_background","assistant_confirm_background"})if(key==k)return 1;
    return -1;
  };
  std::array<views::View*,3> group_cards{};
  auto make_row=[&](const sidebar::PreferenceSpec& spec)->views::View*{
    CHECK_LT(spec.category,preference_sections_.size());
    if(const int group=group_of(spec);group>=0){
      auto*& card=group_cards[group];
      if(!card){
        card=preference_sections_[spec.category].view->AddChildView(std::make_unique<PreferenceSurface>(false,base::BindRepeating(&WorkspaceShell::SchedulePreferenceChrome,weak),base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){return shell&&shell->PreferenceChromeVisible();},weak)));
        SetSidebarPanelLayout(card,true,gfx::Insets(16),16);
        if (group < 2) {
          auto* heading=card->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(heading,true,gfx::Insets(),5);
          copy(heading,group?T(u"Zabezpieczenia"):T(u"Uprawnienia nowych sesji"),kInk,1,gfx::Font::Weight::SEMIBOLD,true);
          copy(heading,group?T(u"Nie dają asystentowi dostępu. Dokładają blokadę do tego, co już może."):T(u"Każda nowa sesja startuje z tymi uprawnieniami. Ograniczenie działa od razu, także w trwającej sesji; szerszy dostęp obowiązuje od nowej sesji."),kMuted,-1,gfx::Font::Weight::NORMAL,true);
        }
        preference_groups_.push_back({card,{}});
      }
      auto* row=card->AddChildView(std::make_unique<views::View>());
      auto* labels=row->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(labels,true,gfx::Insets(),3);
      copy(labels,text(spec.title),kInk,0,gfx::Font::Weight::MEDIUM,true);
      copy(labels,text(spec.detail),kMuted,-1,gfx::Font::Weight::NORMAL,true);
      SetSidebarPanelLayout(row,false,gfx::Insets(),20,labels,true);
      for(auto& entry:preference_groups_)if(entry.card==card)entry.rows.push_back(row);
      preference_sections_[spec.category].rows.push_back({row,base::i18n::ToLower(text(catalogue.categories[spec.category])+u" "+text(spec.title)+u" "+text(spec.detail))});return row;
    }
    auto* row=preference_sections_[spec.category].view->AddChildView(std::make_unique<PreferenceSurface>(false,base::BindRepeating(&WorkspaceShell::SchedulePreferenceChrome,weak),base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){return shell&&shell->PreferenceChromeVisible();},weak)));
    auto* labels=row->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(labels,true,gfx::Insets(),5);
    copy(labels,text(spec.title),kInk,0,gfx::Font::Weight::MEDIUM,true);copy(labels,text(spec.detail),kMuted,-1,gfx::Font::Weight::NORMAL,true);SetSidebarPanelLayout(row,false,gfx::Insets(16),20,labels,true);
    preference_sections_[spec.category].rows.push_back({row,base::i18n::ToLower(text(catalogue.categories[spec.category])+u" "+text(spec.title)+u" "+text(spec.detail))});return row;
  };
  constexpr size_t kSiteSection = 3;
  auto& sites = preference_sections_[kSiteSection];
  constexpr auto kGroupTitles = std::to_array({
      u"Dostęp do urządzenia", u"Zawartość witryn", u"Pozostałe uprawnienia"});
  for (size_t i = 0; i < kSiteCategoryGroups.size(); ++i) {
    auto* card = sites.view->AddChildView(std::make_unique<PreferenceSurface>(
        false, base::BindRepeating(&WorkspaceShell::SchedulePreferenceChrome, weak),
        base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell) {
          return shell && shell->PreferenceChromeVisible();
        }, weak)));
    SetSidebarPanelLayout(card, true, gfx::Insets(16), 12);
    copy(card, T(kGroupTitles[i]), kInk, 1, gfx::Font::Weight::SEMIBOLD, true);
    preference_groups_.push_back({card, {}});
    for (const auto& category : kSiteCategoryGroups[i]) {
      const auto title = T(category.title);
      const std::string key = std::string(kSiteDefaultPrefix) + category.key;
      auto* row = card->AddChildView(std::make_unique<views::View>());
      auto* label = copy(row, title, kInk, 0, gfx::Font::Weight::MEDIUM, true);
      auto* status = copy(row, T(u"Niedostępne w tej wersji"), kMuted, -1,
                          gfx::Font::Weight::NORMAL, false);
      unavailable_preferences_[key] = status;
      auto* picker = ChoicePicker(row, title, {});
      preference_pickers_[key] = picker;
      SetPickerCallback(picker, base::BindRepeating(
          [](base::WeakPtr<WorkspaceShell> shell, std::string key) {
            if (shell) {
              const auto index = PickerIndex(shell->preference_pickers_.at(key));
              if (index)
                shell->WritePreference(key, static_cast<int>(*index));
            }
          }, weak, key));
      SetSidebarPanelLayout(row, false, gfx::Insets(), 16, label, true);
      sites.rows.push_back({row, base::i18n::ToLower(T(u"Uprawnienia stron") + u" " +
                                                    title + u" " + base::UTF8ToUTF16(key))});
      preference_groups_.back().rows.push_back(row);
    }
  }
  for(const auto& spec:catalogue.rows){
    const std::string key(spec.key);
    if (spec.kind == Kind::Toggle &&
        std::ranges::find(kSitePreferenceKeys, key) != kSitePreferenceKeys.end())
      continue;
    if ((spec.kind == Kind::SiteEditor || spec.kind == Kind::SiteRules) &&
        !callbacks_.write_site_preference)
      continue;
    auto* row=make_row(spec);const auto title=text(spec.title);
    if (key == "referrers" || key == "https_only" || key == "third_party_cookies" ||
        key == "do_not_track" || key == "assistant_background" ||
        key == "assistant_confirm_background" || key == "assistant_concurrency") {
      auto* unavailable = copy(row->children().front(), T(u"Niedostępne w tej wersji"),
                               kMuted, -1, gfx::Font::Weight::MEDIUM, true);
      unavailable->SetVisible(false);
      unavailable_preferences_[key] = unavailable;
    }
    if(spec.kind==Kind::Theme||spec.kind==Kind::Search||spec.kind==Kind::Picker||spec.kind==Kind::Language||spec.kind==Kind::TimeMachineDays){
      auto* control=ChoicePicker(row,title,strings(spec.choices));
      if(spec.kind==Kind::TimeMachineDays){time_machine_days_picker_=control;SetPickerCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell)shell->SetTimeMachine(shell->time_machine_enabled_,std::array{7,30,90}[std::min<size_t>(2,PickerIndex(shell->time_machine_days_picker_).value_or(1))]);},weak));}
      else if(spec.kind==Kind::Language){language_picker_=control;SetPickerCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell)shell->SetUiLanguageChoice(PickerIndex(shell->language_picker_).value_or(0));},weak));}
      else if(spec.kind==Kind::Theme){theme_picker_=control;SetPickerCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell)shell->SetThemeMode(static_cast<ThemeMode>(PickerIndex(shell->theme_picker_).value_or(0)));},weak));}
      else if(spec.kind==Kind::Search){search_engine_picker_=control;SetPickerCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(!shell)return;const size_t index=PickerIndex(shell->search_engine_picker_).value_or(0);if(index<shell->tools_.providers.size())shell->SetDefaultSearchProvider(shell->tools_.providers[index].keyword);},weak));}
      else{preference_pickers_[key]=control;SetPickerCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,std::string key){if(shell){auto index=PickerIndex(shell->preference_pickers_.at(key));if(index)shell->WritePreference(key,static_cast<int>(*index));}},weak,key));}
      continue;
    }
    if(spec.kind==Kind::Pinned||spec.kind==Kind::Animations||spec.kind==Kind::WorkspaceNames||spec.kind==Kind::FoldersCollapsed||spec.kind==Kind::Toggle||spec.kind==Kind::TimeMachine){
      auto* control=PreferenceToggle(row,title);
      if(spec.kind==Kind::TimeMachine){time_machine_check_=control;SetActionCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell)shell->SetTimeMachine(ToggleOn(shell->time_machine_check_),shell->time_machine_days_);},weak));}
      else if(spec.kind==Kind::Pinned){sidebar_check_=control;SetActionCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell)shell->SetPinned(ToggleOn(shell->sidebar_check_));},weak));}
      else if(spec.kind==Kind::Animations){animations_check_=control;SetActionCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell)shell->SetWorkspaceAnimations(ToggleOn(shell->animations_check_));},weak));}
      else if(spec.kind==Kind::FoldersCollapsed){folders_collapsed_check_=control;SetActionCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell)shell->SetPinnedFoldersCollapsed(ToggleOn(shell->folders_collapsed_check_));},weak));}
      else if(spec.kind==Kind::WorkspaceNames){workspace_names_check_=control;SetActionCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell)shell->SetWorkspaceNames(ToggleOn(shell->workspace_names_check_));},weak));}
      else{preference_toggles_[key]=control;SetActionCallback(control,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,std::string key){if(shell)shell->WritePreference(key,ToggleOn(shell->preference_toggles_.at(key)));},weak,key));}
      constexpr std::string_view kExtensionPrefix = "extension_enabled.";
      if (callbacks_.open_extension_popup && key.starts_with(kExtensionPrefix)) {
        const auto id = key.substr(kExtensionPrefix.size());
        auto* icon = row->AddChildView(std::make_unique<views::ImageView>());
        icon->SetImageSize(gfx::Size(16, 16));
        icon->SetVisible(false);
        extension_action_icons_[id] = icon;
        auto* badge = row->AddChildView(std::make_unique<views::Label>());
        badge->SetMaximumWidthSingleLine(56);
        badge->SetElideBehavior(gfx::ELIDE_TAIL);
        badge->SetBorder(views::CreateEmptyBorder(gfx::Insets::VH(1, 4)));
        badge->SetVisible(false);
        extension_action_badges_[id] = badge;
        if (const auto appearance = extension_action_appearance_.find(id);
            appearance != extension_action_appearance_.end()) {
          SetExtensionActionAppearance(id, appearance->second.icon,
                                       appearance->second.badge, appearance->second.color);
        }
        auto* popup = PreferenceAction(
            row, base::BindRepeating(callbacks_.open_extension_popup, id), T(u"Otwórz"));
        popup->GetViewAccessibility().SetName(TF(u"Otwórz rozszerzenie: {}", {title}));
        extension_popup_buttons_["extension_popup." + id] = popup;
      }
      if (callbacks_.open_extension_popup && key.starts_with(kExtensionPrefix)) {
        const auto pin_key = "extension_pinned." + key.substr(kExtensionPrefix.size());
        auto* pin = PreferenceAction(row, {}, T(u"Przypnij do paska"));
        extension_pin_buttons_[pin_key] = pin;
        SetActionCallback(pin, base::BindRepeating(
            [](base::WeakPtr<WorkspaceShell> shell, std::string key) {
              if (!shell || !shell->callbacks_.read_preferences)
                return;
              const auto prefs = shell->callbacks_.read_preferences.Run();
              const auto current = prefs.find(key);
              if (current != prefs.end() && current->second.editable)
                shell->WritePreference(key, !current->second.value);
            }, weak, pin_key));
      }
      if (callbacks_.open_extension_options && key.starts_with(kExtensionPrefix)) {
        const auto id = key.substr(kExtensionPrefix.size());
        auto* options = PreferenceAction(
            row, base::BindRepeating(callbacks_.open_extension_options, id), T(u"Opcje"));
        options->GetViewAccessibility().SetName(TF(u"Opcje rozszerzenia: {}", {title}));
        extension_options_buttons_["extension_options." + id] = options;
      }
      if (callbacks_.uninstall_extension && key.starts_with(kExtensionPrefix)) {
        auto* remove = PreferenceAction(row, {}, T(u"Usuń"));
        remove->GetViewAccessibility().SetName(TF(u"Usuń: {}", {title}));
        SetActionCallback(remove, base::BindRepeating(
            callbacks_.uninstall_extension, key.substr(kExtensionPrefix.size())));
        extension_remove_buttons_[key] = remove;
      }
      continue;
    }
    if(spec.kind==Kind::Text){
      auto* field=AddEditor(row->children().front());field->GetViewAccessibility().SetName(title);field->SetPlaceholderText(text(spec.placeholder));
      field->SetCallbacks(base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,std::string key){if(shell)shell->PreferenceTextEdited(key);},weak,key),base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,EditorControl* field,const ui::KeyEvent& event){return shell&&shell->HandlePreferenceEditorKey(field,event);},weak,base::Unretained(field)));field->view()->SetPreferredSize(gfx::Size(240,36));preference_textfields_[key]=field;
      auto* save=PreferenceAction(row,{},text(spec.button));BindFormCommand(save,sidebar::FormCommand::PreferenceText,key);save->SetTooltipText(text(spec.button_ax));save->GetViewAccessibility().SetName(text(spec.button_ax));preference_save_buttons_[key]=save;continue;
    }
    switch(spec.kind){
      case Kind::Action:{
        if (key == "install_extension") {
          install_extension_button_ = PreferenceAction(row, {}, text(spec.button));
          install_extension_button_->GetViewAccessibility().SetName(title);
          SetActionCallback(install_extension_button_, callbacks_.install_extension);
          break;
        }
        if(spec.action==Action::ClearTimeline){
          auto* button=PreferenceAction(row,{},text(spec.button));button->GetViewAccessibility().SetName(text(spec.title));
          SetActionCallback(button,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(shell&&shell->callbacks_.clear_timeline)shell->callbacks_.clear_timeline.Run();},weak));break;
        }
        using Command=sidebar::FormCommand;Command command=Command::None;
        switch(spec.action){
          case Action::History:command=Command::History;break;
          case Action::Workspace:command=Command::Workspace;break;
          case Action::Passwords:command=Command::Passwords;break;
          case Action::Profiles:command=Command::Profiles;break;
          case Action::Import:command=Command::Import;break;
          case Action::Proxy:command=Command::Proxy;break;
          case Action::Certificates:command=Command::Certificates;break;
          case Action::Providers:command=Command::Providers;break;
          case Action::Shortcuts:command=Command::Shortcuts;break;
          case Action::TimeMachine:command=Command::TimeMachine;break;
          default:CHECK(false);
        }
        auto* button=PreferenceAction(row,{},text(spec.button));BindFormCommand(button,command);button->SetTooltipText(text(spec.button_ax));button->GetViewAccessibility().SetName(text(spec.button_ax));break;
      }
      case Kind::Updates: {
        auto* labels = row->children().front().get();
        auto* status_row = labels->AddChildView(std::make_unique<views::View>());
        update_preferences_spinner_ = status_row->AddChildView(std::make_unique<views::Throbber>());
        update_preferences_status_ = copy(status_row, u"", kInk, 0, gfx::Font::Weight::NORMAL, true);
        SetSidebarPanelLayout(status_row, false, gfx::Insets(), Metrics().space_2,
                              update_preferences_status_, true);
        update_preferences_check_ = PreferenceAction(row, {}, T(u"Sprawdź aktualizacje"));
        SetActionCallback(update_preferences_check_, base::BindRepeating(&WorkspaceShell::CheckForUpdates, weak));
        update_preferences_action_ = PreferenceAction(labels, {}, T(u"Otwórz stronę wydania"));
        SetActionCallback(update_preferences_action_, base::BindRepeating(&WorkspaceShell::RunUpdateAction, weak));
        break;
      }
      case Kind::AutoUpdateCheck:
      case Kind::AutoUpdateDownload: {
        auto& toggle = spec.kind == Kind::AutoUpdateCheck ? auto_update_check_toggle_ : auto_update_download_toggle_;
        toggle = PreferenceToggle(row, title);
        SetActionCallback(toggle, base::BindRepeating(&WorkspaceShell::SetAutomaticUpdates, weak));
        break;
      }
      case Kind::Directory:
        download_directory_button_=PreferenceAction(row,{},text(spec.button));BindFormCommand(download_directory_button_,sidebar::FormCommand::PreferenceDirectory);download_directory_button_->SetTooltipText(text(spec.button_ax));download_directory_button_->GetViewAccessibility().SetName(text(spec.button_ax));download_directory_label_=copy(row->children().front().get(),u"",kMuted,-1,gfx::Font::Weight::NORMAL,true);break;
      case Kind::SiteEditor:{
        const auto& site=catalogue.site;auto* fields=row->children().front().get();site_origin_=AddEditor(fields);site_origin_->GetViewAccessibility().SetName(text(site.origin_ax));site_origin_->SetPlaceholderText(text(site.placeholder));site_origin_->SetCallbacks({},base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,EditorControl* field,const ui::KeyEvent& event){return shell&&shell->HandlePreferenceEditorKey(field,event);},weak,base::Unretained(site_origin_.get())));
        site_type_=ChoicePicker(fields,text(site.type_ax),strings(site.types));site_policy_=ChoicePicker(fields,text(site.policy_ax),strings(sidebar::preference_site_policies(0)));
        SetPickerCallback(site_type_,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){if(!shell)return;std::vector<std::u16string> choices;for(const auto& choice:sidebar::preference_site_policies(PickerIndex(shell->site_type_).value_or(0)))choices.push_back(base::UTF8ToUTF16(std::string(choice)));ReplacePickerLabels(shell->site_policy_,choices);},weak));
        BindFormCommand(PreferenceAction(row,{},text(site.save)),sidebar::FormCommand::PreferenceSite);break;
      }
      case Kind::AssistantBackends:
        assistant_backends_list_=row->children().front()->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(assistant_backends_list_,true,gfx::Insets::TLBR(6,0,0,0),10);break;
      case Kind::AssistantModels:{
        auto* fields=row->children().front().get();
        assistant_models_list_=fields->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(assistant_models_list_,true,gfx::Insets::TLBR(6,0,0,0),8);
        auto* add=fields->AddChildView(std::make_unique<views::View>());
        assistant_add_backend_=ChoicePicker(add,T(u"Backend nowego modelu"),{});
        assistant_add_model_=AddEditor(add);assistant_add_model_->SetPlaceholderText(T(u"ID modelu, np. haiku"));assistant_add_model_->GetViewAccessibility().SetName(T(u"ID nowego modelu"));assistant_add_model_->view()->SetPreferredSize(gfx::Size(200,36));
        auto submit=base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell){
          if(!shell||!shell->callbacks_.write_assistant)return;
          const auto id=base::UTF16ToUTF8(base::TrimWhitespace(shell->assistant_add_model_->GetText(),base::TRIM_ALL));if(id.empty())return;
          const size_t backend=PickerIndex(shell->assistant_add_backend_).value_or(0);
          if(backend>=shell->assistant_add_providers_.size())return;
          shell->assistant_add_model_->SetText(u"");
          shell->callbacks_.write_assistant.Run(base::DictValue().Set("command","add").Set("provider",shell->assistant_add_providers_[backend]).Set("id",id));
        },weak);
        assistant_add_model_->SetCallbacks({},base::BindRepeating([](base::RepeatingClosure submit,const ui::KeyEvent& event){
          if(event.type()!=ui::EventType::kKeyPressed||event.key_code()!=ui::VKEY_RETURN)return false;submit.Run();return true;},submit));
        assistant_add_button_=PreferenceAction(add,base::BindRepeating([](base::RepeatingClosure submit,const ui::Event&){submit.Run();},submit),T(u"Dodaj model"));
        SetSidebarPanelLayout(add,false,gfx::Insets::TLBR(4,0,0,0),8,assistant_add_model_->view(),true);
        break;
      }
      case Kind::AdBlocking:{
        // Lists (design: Zitter — Ad blocking preferences): status and the
        // update action at the end of the card, the lists under its title.
        ad_blocking_list_=row->children().front()->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(ad_blocking_list_,true,gfx::Insets::TLBR(8,0,0,0),8);
        break;
      }
      case Kind::AdBlockingSites:
        ad_blocking_sites_=row->children().front()->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(ad_blocking_sites_,true,gfx::Insets(),6);break;
      case Kind::AdBlockingRules:
        // A summary here; the rules themselves are edited in their own dialog.
        ad_blocking_rules_=row->children().front()->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(ad_blocking_rules_,true,gfx::Insets::TLBR(4,0,0,0),4);
        PreferenceAction(row,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,const ui::Event&){
          if(shell&&shell->callbacks_.open_ad_blocking_rules)shell->callbacks_.open_ad_blocking_rules.Run();},weak),T(u"Edytuj reguły"));
        break;
      case Kind::SiteRules:
        site_rules_card_=row;site_rules_list_=row->children().front()->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(site_rules_list_,true,gfx::Insets(),8);break;
      case Kind::ClearData:{
        const auto& clear=catalogue.clear;auto* fields=row->children().front().get();clear_data_period_=ChoicePicker(fields,text(clear.period_ax),strings(clear.periods));auto* checks=fields->AddChildView(std::make_unique<SceneCheckboxGroup>(8));CHECK_EQ(clear.checks.size(),3u);
        clear_history_=AddImportCheck(checks,text(clear.checks[0]),{});clear_cookies_=AddImportCheck(checks,text(clear.checks[1]),{});clear_cache_=AddImportCheck(checks,text(clear.checks[2]),{});SetCheckValue(clear_cache_,true);
        clear_data_button_=PreferenceAction(row,{},text(clear.action));BindFormCommand(clear_data_button_,sidebar::FormCommand::PreferenceClear);break;
      }
      case Kind::ShortcutHint:row->SetTooltipText(text(spec.tooltip));break;
      default:CHECK(false);
    }
  }
}
void WorkspaceShell::RefreshGeneralControls() {
  if (!general_widget_) return;
  bool profile_changed=false;
  if(preferences_form_)profile_changed=preferences_form_->form->preference_profile(state_.profile_id);
  if(profile_changed){CancelChoiceInteractions(general_widget_->GetContentsView());
    CancelSceneActions(general_widget_->GetContentsView());
  }
  SyncPickerIndex(theme_picker_,static_cast<size_t>(theme_mode_));
  std::vector<std::pair<std::string,std::u16string>> provider_choices;
  size_t provider_index=0;
  const std::string implicit=search_engine_==SearchEngine::kGoogle?"g":search_engine_==SearchEngine::kBing?"b":"d";
  const std::string selected=tools_.default_keyword.empty()?implicit:tools_.default_keyword;
  for(size_t i=0;i<tools_.providers.size();++i){
    provider_choices.emplace_back(tools_.providers[i].keyword,base::UTF8ToUTF16(tools_.providers[i].name));
    if(tools_.providers[i].keyword==selected)provider_index=i;
  }
  ReplacePickerOptions(search_engine_picker_,provider_choices);
  SyncPickerIndex(search_engine_picker_,provider_choices.empty()?std::nullopt:std::optional<size_t>(provider_index));
  SetToggleOn(sidebar_check_,pinned_);
  SetToggleOn(animations_check_,workspace_animations_);
  SetToggleOn(time_machine_check_,time_machine_enabled_);
  SyncPickerIndex(time_machine_days_picker_,time_machine_days_==7?0:time_machine_days_==90?2:1);
  SetToggleOn(workspace_names_check_,workspace_names_);
  SetToggleOn(folders_collapsed_check_,folders_collapsed_);
  {const auto stored=StoredUiLanguage(callbacks_.locale_preferences);SyncPickerIndex(language_picker_,stored=="pl"?1:stored=="en"?2:0);}
  if (profile_changed) {
    if (site_origin_) {
      site_origin_->SetText(u"");
      ResetPreferenceRuleLimit();
      RefreshSitePreferences();
    }
  }
  // Rust owns availability/managed copy; Views keeps its original strings.
  const bool rust_copy =
      bool(preferences_form_);
  auto control_view = [&](bool toggle, bool present, bool editable, std::u16string native) {
    if (rust_copy) return base::UTF8ToUTF16(std::string(sidebar::preference_control_view(toggle ? sidebar::PreferenceControlKind::Toggle : sidebar::PreferenceControlKind::Text, present, editable).tooltip));
    return native;
  };
  if (rust_copy) SetPanelText(preferences_profile_,base::UTF8ToUTF16(std::string(sidebar::preferences_profile_banner(base::UTF16ToUTF8(state_.profile_name)))));
  else
  SetPanelText(preferences_profile_,TF(u"Profil: {} · Ustawienia wspólne dla aplikacji są oznaczone w opisach.", {state_.profile_name}));
  const auto values = callbacks_.read_preferences ? callbacks_.read_preferences.Run() : BrowserPreferences();
  SetPanelText(download_directory_label_,callbacks_.download_directory ? callbacks_.download_directory.Run() : u"");
  for (const auto& [key, field] : preference_textfields_) {
    auto it = values.find(key);
    const bool enabled = it != values.end() && it->second.editable;
    field->view()->SetEnabled(enabled);
    preference_save_buttons_.at(key)->SetEnabled(enabled);
    if (SyncPreferenceText(key,it!=values.end(),enabled,field->IsIMEComposing(),profile_changed)) {
      field->SetText(base::UTF8ToUTF16(it->second.text));
    }
    field->view()->SetTooltipText(control_view(false, it != values.end(), enabled, it == values.end() ? T(u"Ustawienie jest niedostępne") : !enabled ? T(u"To ustawienie jest zarządzane") : T(u"Zapisz przyciskiem lub klawiszem Enter")));
  }
  auto directory = values.find("download_directory");
  download_directory_button_->SetEnabled(directory != values.end() && directory->second.editable);
  for (const auto& [key, control] : preference_toggles_) {
    auto it = values.find(key);
    control->SetEnabled(it != values.end() && it->second.editable);
    if (const auto unavailable = unavailable_preferences_.find(key);
        unavailable != unavailable_preferences_.end())
      unavailable->second->SetVisible(it == values.end());
    if (it != values.end() || key.starts_with("extension_enabled") ||
        key.starts_with("extension_user_scripts."))
      SetToggleOn(control, it != values.end() && it->second.value != 0);
    control->SetTooltipText(control_view(true, it != values.end(), it != values.end() && it->second.editable, it == values.end() ? T(u"Profil nie jest jeszcze gotowy") :
        !it->second.editable ? T(u"To ustawienie jest zarządzane") : T(u"Dotyczy aktywnego profilu")));
  }
  for (const auto& [key, pin] : extension_pin_buttons_) {
    const auto value = values.find(key);
    pin->parent()->SetVisible(value != values.end());
    pin->SetEnabled(value != values.end() && value->second.editable);
    SetActionText(pin, value != values.end() && value->second.value != 0
                           ? T(u"Odepnij z paska") : T(u"Przypnij do paska"));
  }
  for (const auto& [key, popup] : extension_popup_buttons_) {
    const auto value = values.find(key);
    const bool visible = value != values.end();
    popup->parent()->SetVisible(visible);
    popup->SetEnabled(visible && value->second.editable);
  }
  for (const auto& [key, options] : extension_options_buttons_) {
    const auto value = values.find(key);
    const bool visible = value != values.end();
    options->parent()->SetVisible(visible);
    options->SetEnabled(visible && value->second.editable);
  }
  for (const auto& [key, remove] : extension_remove_buttons_) {
    const auto value = values.find(key);
    remove->SetVisible(value != values.end());
    remove->SetEnabled(value != values.end() && value->second.editable);
  }
  for (const auto& [key, control] : preference_pickers_) {
    auto it = values.find(key);
    control->SetEnabled(it != values.end() && it->second.editable);
    if (const auto unavailable = unavailable_preferences_.find(key);
        unavailable != unavailable_preferences_.end())
      unavailable->second->SetVisible(it == values.end());
    if (unavailable_preferences_.contains(key)) {
      control->SetVisible(it != values.end());
      if (it != values.end()) {
        const auto& policies = it->second.text;
        std::vector<std::pair<std::string, std::u16string>> options = {{"block", T(u"Blokuj")}};
        if (policies.find('p') != std::string::npos)
          options.emplace_back("ask", T(u"Pytaj"));
        if (policies.find('a') != std::string::npos)
          options.emplace_back("allow", T(u"Zezwalaj"));
        ReplacePickerOptions(control, options);
      }
    }
    if (it != values.end()) SyncPickerIndex(control,it->second.value < 0 ? std::nullopt : std::optional<size_t>(it->second.value));
  }
  RefreshUpdateControls();
  BuildAssistantPreferences();
  BuildAdBlockingPreferences();
}
void WorkspaceShell::RefreshAdBlockingPreferences() {
  if(ad_blocking_refresh_pending_)return;ad_blocking_refresh_pending_=true;
  base::SingleThreadTaskRunner::GetCurrentDefault()->PostTask(FROM_HERE,base::BindOnce([](base::WeakPtr<WorkspaceShell> shell){
    if(!shell)return;shell->ad_blocking_refresh_pending_=false;shell->BuildAdBlockingPreferences();
  },weak_factory_.GetWeakPtr()));
}
void WorkspaceShell::BuildAdBlockingPreferences() {
  if(!ad_blocking_list_||!ad_blocking_sites_||!ad_blocking_rules_||!callbacks_.read_ad_blocking)return;
  auto data=callbacks_.read_ad_blocking.Run();
  const auto snapshot=base::WriteJson(data).value_or("")+(ad_blocking_sources_open_?"1":"0");
  if(snapshot==ad_blocking_snapshot_)return;
  ad_blocking_snapshot_=snapshot;
  auto weak=weak_factory_.GetWeakPtr();
  auto text=[](const base::DictValue& d,const char* key){const auto* v=d.FindString(key);return v?base::UTF8ToUTF16(*v):std::u16string();};
  auto write=[](base::WeakPtr<WorkspaceShell> shell,base::DictValue command){
    if(!shell||!shell->callbacks_.write_ad_blocking)return;shell->callbacks_.write_ad_blocking.Run(std::move(command));shell->RefreshAdBlockingPreferences();};
  auto muted=[&](views::View* parent,std::u16string value){return AddPreferenceCopy(parent,std::move(value),kMuted,-1,static_cast<int>(gfx::Font::Weight::NORMAL),true);};
  const bool available=data.FindBool("available").value_or(false);
  const bool updating=data.FindBool("updating").value_or(false);
  const bool list_updates_available=data.FindBool("list_updates_available").value_or(true);

  // Lists: one compact row each, a count in `url`, "Zawsze" or a switch. The
  // stand-ins and the Adblock Warning Removal List live under "Ukrywaj
  // blokowanie przed stronami".
  ad_blocking_update_ = nullptr;
  ad_blocking_list_->RemoveAllChildViews();
  if(list_updates_available) {
    // The lists' state, and updating them now, on one line above them.
    const auto error=text(data,"error");
    auto* line=ad_blocking_list_->AddChildView(std::make_unique<views::View>());
    auto* status=muted(line,updating?T(u"Pobieram listy…"):!error.empty()?TF(u"Nie udało się pobrać: {}",{error})
                                 :data.FindString("updated")&&!data.FindString("updated")->empty()?TF(u"Aktualne · {}",{text(data,"updated")}):std::u16string());
    if(!error.empty())if(auto* copy=views::AsViewClass<PreferenceCopy>(status))copy->SetInk(Palette(ad_blocking_list_).danger);
    ad_blocking_update_=PreferenceAction(line,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,const ui::Event&){
      write(shell,base::DictValue().Set("command","update"));},write,weak),T(u"Aktualizuj"));
    if(auto* button=views::AsViewClass<SceneTextButton>(ad_blocking_update_))button->SetKind(6);
    SetSidebarPanelLayout(line,false,gfx::Insets(),12,status,true);
  }
  if(const auto* lists=data.FindList("lists"))for(const auto& item:*lists){
    const auto& list=item.GetDict();
    const std::string id=list.FindString("id")?*list.FindString("id"):std::string();
    if(list_updates_available&&(id=="zitter"||id=="antiadblock"))continue;
    const bool optional=list.FindBool("optional").value_or(false),enabled=list.FindBool("enabled").value_or(true);
    auto* line=ad_blocking_list_->AddChildView(std::make_unique<views::View>());
    auto* labels=line->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(labels,true,gfx::Insets(),2);
    AddPreferenceCopy(labels,text(list,"name"),kInk,0,static_cast<int>(gfx::Font::Weight::NORMAL),false);
    if(id=="ublock")muted(labels,T(u"Więcej reguł przeciw wykrywaniu · około 2,5 MB"));
    const int rules=list.FindInt("rules").value_or(0);
    auto* count=muted(line,enabled&&rules?base::FormatNumber(rules):std::u16string(u"—"));
    if(auto* copy=views::AsViewClass<PreferenceCopy>(count))copy->SetTextStyle(8);
    if(optional){
      auto* toggle=PreferenceToggle(line,TF(u"Używaj listy {}",{text(list,"name")}));
      SetToggleOn(toggle,enabled);toggle->SetEnabled(available);
      SetActionCallback(toggle,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,std::string id,views::View* toggle){
        write(shell,base::DictValue().Set("command","list").Set("list",id).Set("enabled",ToggleOn(toggle)));
      },write,weak,id,base::Unretained(toggle)));
    }else{
      auto* always=muted(line,T(u"Zawsze"));always->SetPreferredSize(gfx::Size(38,always->GetPreferredSize().height()));
    }
    SetSidebarPanelLayout(line,false,gfx::Insets(),16,labels,true);
  }
  // Attribution, as EasyList's license asks: behind one quiet action.
  if(list_updates_available) {
    auto* sources=PreferenceAction(ad_blocking_list_,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,const ui::Event&){
      if(!shell)return;shell->ad_blocking_sources_open_=!shell->ad_blocking_sources_open_;shell->RefreshAdBlockingPreferences();},weak),
      ad_blocking_sources_open_?T(u"Ukryj źródła i licencje"):T(u"Źródła i licencje"));
    if(auto* button=views::AsViewClass<SceneTextButton>(sources))button->SetKind(6);
    if(ad_blocking_sources_open_)muted(ad_blocking_list_,T(u"EasyList, EasyPrivacy i Adblock Warning Removal List: © autorzy EasyList, licencja GPLv3 lub CC BY-SA 3.0, pobierane z easylist.to. uBlock filters: © autorzy uBlock Origin, licencja GPLv3, pobierane z github.com/uBlockOrigin/uAssets. Zamienniki Zittera są częścią Zittera. Silnik: adblock-rust od Brave, licencja MPL-2.0."));
  }
  if(ad_blocking_update_)ad_blocking_update_->SetEnabled(!updating&&available);

  // Sites without blocking: each with the action that turns blocking back on.
  ad_blocking_sites_->RemoveAllChildViews();
  if(const auto* sites=data.FindList("sites"))for(const auto& site:*sites)if(site.is_string()){
    auto* line=ad_blocking_sites_->AddChildView(std::make_unique<views::View>());
    auto* name=AddPreferenceCopy(line,base::UTF8ToUTF16(site.GetString()),kInk,0,static_cast<int>(gfx::Font::Weight::NORMAL),false);
    if(auto* copy=views::AsViewClass<PreferenceCopy>(name))copy->SetTextStyle(8);
    auto* on=PreferenceAction(line,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,std::string site,const ui::Event&){
      write(shell,base::DictValue().Set("command","site_remove").Set("site",site));},write,weak,site.GetString()),T(u"Włącz"));
    on->GetViewAccessibility().SetName(TF(u"Włącz blokowanie na {}",{base::UTF8ToUTF16(site.GetString())}));
    SetSidebarPanelLayout(line,false,gfx::Insets(),12,name,true);
  }
  ad_blocking_sites_->SetVisible(!ad_blocking_sites_->children().empty());

  // The rules summary: how many, and per site; a site with a rule that
  // stopped working says so.
  ad_blocking_rules_->RemoveAllChildViews();
  {
    const auto* rule_sites=data.FindList("rule_sites");
    int total=0;std::u16string per_site;
    for(size_t i=0;rule_sites&&i<rule_sites->size();++i){
      const auto& entry=(*rule_sites)[i].GetDict();const int count=entry.FindInt("count").value_or(0);total+=count;
      const auto site=text(entry,"site");
      per_site+=(per_site.empty()?u"":u" · ")+(site.empty()?T(u"ogólne"):site)+u" "+base::NumberToString16(count);
      if(entry.FindBool("stale").value_or(false))per_site+=u" "+T(u"(nie działa)");
    }
    if(!total)muted(ad_blocking_rules_,T(u"Brak. Dodaj regułę w edytorze albo poproś asystenta."));
    else{
      AddPreferenceCopy(ad_blocking_rules_,TF(u"Reguły: {} · witryny: {}",{base::NumberToString16(total),base::NumberToString16(rule_sites->size())}),kInk,0,static_cast<int>(gfx::Font::Weight::NORMAL),false);
      auto* sites=muted(ad_blocking_rules_,per_site);if(auto* copy=views::AsViewClass<PreferenceCopy>(sites))copy->SetTextStyle(8);
    }
  }
  RefreshChoiceViewports(ad_blocking_list_->parent());
  if(general_widget_)general_widget_->GetContentsView()->InvalidateLayout();
}
void WorkspaceShell::RefreshAssistantPreferences() {
  // Rows rebuild after the click that changed them has finished.
  if(assistant_refresh_pending_)return;assistant_refresh_pending_=true;
  base::SingleThreadTaskRunner::GetCurrentDefault()->PostTask(FROM_HERE,base::BindOnce([](base::WeakPtr<WorkspaceShell> shell){
    if(!shell)return;shell->assistant_refresh_pending_=false;
    // The first-run wizard can be open before Settings has ever been created.
    if (shell->general_widget_) shell->RefreshGeneralControls();
    else shell->BuildAssistantPreferences();
  },weak_factory_.GetWeakPtr()));
}
void WorkspaceShell::BuildAssistantBackendCards(views::View* list, const base::DictValue& data,
                                                std::string_view only_provider) {
  auto weak=weak_factory_.GetWeakPtr();
  const bool onboarding = !only_provider.empty();
  const bool enabled=data.FindBool("enabled").value_or(false);
  auto layout_section = [onboarding](views::View* view, bool vertical, gfx::Insets insets,
                                     int spacing, views::View* flex = nullptr) {
    if (!onboarding) {
      SetSidebarPanelLayout(view, vertical, insets, spacing, flex, flex != nullptr);
      return;
    }
    auto* layout = view->SetLayoutManager(std::make_unique<views::BoxLayout>(
        vertical ? views::BoxLayout::Orientation::kVertical
                 : views::BoxLayout::Orientation::kHorizontal,
        insets, spacing));
    if (!vertical) layout->set_cross_axis_alignment(views::BoxLayout::CrossAxisAlignment::kCenter);
    if (flex) layout->SetFlexForView(flex, 1);
  };
  auto text=[](const base::DictValue& d,const char* key){const auto* v=d.FindString(key);return v?base::UTF8ToUTF16(*v):std::u16string();};
  auto write=[](base::WeakPtr<WorkspaceShell> shell,base::DictValue command){if(shell&&shell->callbacks_.write_assistant)shell->callbacks_.write_assistant.Run(std::move(command));};
  list->RemoveAllChildViews();
  const auto* backends=data.FindList("backends");const auto* status=data.FindList("status");
  bool showed_backend = false;
  for(size_t i=0;backends&&i<backends->size();++i){
    const auto& backend=(*backends)[i].GetDict();const auto provider=*backend.FindString("provider");
    if (!only_provider.empty() && provider != only_provider) continue;
    showed_backend = true;
    const base::DictValue* state=status&&i<status->size()?&(*status)[i].GetDict():nullptr;
    const int tone=state?state->FindInt("tone").value_or(0):0;
    const bool checking=state&&state->FindBool("checking").value_or(false);
    auto* card=list->AddChildView(std::make_unique<views::View>());
    if (onboarding)
      card->SetBackground(views::CreateRoundedRectBackground(Palette(list).bg_raised, 12));
    layout_section(card, true, onboarding ? gfx::Insets(16) : gfx::Insets::TLBR(6, 0, 14, 0),
                   onboarding ? 10 : 8);
    auto* line=card->AddChildView(std::make_unique<views::View>());
    auto* labels=line->AddChildView(std::make_unique<views::View>());layout_section(labels,true,gfx::Insets(),4);
    AddPreferenceCopy(labels,text(backend,"label"),kInk,0,static_cast<int>(gfx::Font::Weight::MEDIUM),false);
    AddPreferenceCopy(labels,u"●  "+(state?text(*state,"state"):T(u"Sprawdzam…")),tone==1?kOk:tone==2?kError:kMuted,-1,static_cast<int>(gfx::Font::Weight::MEDIUM),false);
    auto* toggle=PreferenceToggle(line,TF(u"Pokazuj {} w panelu",{text(backend,"label")}));
    SetToggleOn(toggle,backend.FindBool("enabled").value_or(true));toggle->SetEnabled(enabled);
    SetActionCallback(toggle,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,std::string provider,views::View* toggle){
      write(shell,base::DictValue().Set("command","backend").Set("provider",provider).Set("enabled",ToggleOn(toggle)));
    },write,weak,provider,base::Unretained(toggle)));
    layout_section(line,false,gfx::Insets(),16,labels);
    if(state)AddPreferenceCopy(card,text(*state,"detail"),kMuted,-1,static_cast<int>(gfx::Font::Weight::NORMAL),true);
    auto* actions=card->AddChildView(std::make_unique<views::View>());
    auto* check=PreferenceAction(actions,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,std::string provider,const ui::Event&){
      write(shell,base::DictValue().Set("command","check").Set("provider",provider));
    },write,weak,provider),checking?T(u"Sprawdzam…"):T(u"Sprawdź połączenie"));
    check->GetViewAccessibility().SetName(TF(u"Sprawdź połączenie z {}",{text(backend,"label")}));check->SetEnabled(enabled&&!checking);
    if (onboarding) views::AsViewClass<SceneTextButton>(check)->SetPrimary();
    if(provider=="openai"){
      const bool saved=data.FindBool("has_saved_key").value_or(false);
      auto* key=PreferenceAction(actions,base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell, views::View* card, const ui::Event&){if(shell)shell->ShowAssistantKeyDialog(card->GetWidget());},weak,base::Unretained(card)),saved?T(u"Zmień klucz API"):T(u"Dodaj klucz API"));key->SetEnabled(enabled);
      if(saved){auto* remove=PreferenceAction(actions,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,const ui::Event&){write(shell,base::DictValue().Set("command","remove_key"));},write,weak),T(u"Usuń klucz"));remove->SetEnabled(enabled);}
    }
    if (provider == "claude" && data.FindBool("claude_login_supported").value_or(false)) {
      auto* login = PreferenceAction(actions, base::BindRepeating([](decltype(write) write,
          base::WeakPtr<WorkspaceShell> shell, const ui::Event&) {
        write(shell, base::DictValue().Set("command", "claude_login"));
      }, write, weak), T(u"Zaloguj się do Claude Code"));
      login->SetEnabled(enabled && !data.FindBool("claude_login_pending").value_or(false));
    }
    if (provider == "ollama") {
      auto* discover = PreferenceAction(actions, base::BindRepeating([](decltype(write) write,
          base::WeakPtr<WorkspaceShell> shell, const ui::Event&) {
        write(shell, base::DictValue().Set("command", "discover").Set("provider", "ollama"));
      }, write, weak), T(u"Wykryj modele"));
      discover->SetEnabled(enabled && !checking);
    }
    if (provider == "codex" || provider == "claude" || provider == "ollama") {
      auto* configure = PreferenceAction(actions, base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,
          views::View* card, std::string provider, std::u16string value, const ui::Event&) {
        if (shell) shell->ShowAssistantBackendInput(card->GetWidget(), provider, value);
      }, weak, base::Unretained(card), provider,
         text(data, provider == "codex" ? "codex_path" : "claude_path")),
         provider == "ollama" ? T(u"Dodaj model") : T(u"Pomoc i konfiguracja"));
      configure->SetEnabled(enabled);
    }
    layout_section(actions,false,gfx::Insets(),8);
    if (onboarding)
      AddPreferenceCopy(card,T(u"Test wysyła krótką wiadomość do wybranego modelu. Nie udostępnia stron ani historii przeglądania."),kMuted,-1,static_cast<int>(gfx::Font::Weight::NORMAL),true);
  }
  if (showed_backend && !onboarding)
    AddPreferenceCopy(list,T(u"Test wysyła krótką wiadomość do wybranego modelu. Nie udostępnia stron ani historii przeglądania."),kMuted,-1,static_cast<int>(gfx::Font::Weight::NORMAL),true);
  if (!showed_backend && onboarding)
    AddPreferenceCopy(list,T(u"Profil nie jest jeszcze gotowy"),kMuted,0,static_cast<int>(gfx::Font::Weight::NORMAL),true);
  list->InvalidateLayout();
  if (auto* owner = list->GetWidget()) owner->GetContentsView()->InvalidateLayout();
}
void WorkspaceShell::BuildAssistantPreferences() {
  if (!callbacks_.read_assistant) return;
  auto data = callbacks_.read_assistant.Run();
  const auto snapshot = base::WriteJson(data).value_or("");
  if (auto* welcome = welcome_assistant_backends_.view(); welcome && snapshot != welcome_assistant_snapshot_) {
    welcome_assistant_snapshot_ = snapshot;
    BuildAssistantBackendCards(welcome, data, welcome_assistant_provider_);
  }
  if (!assistant_backends_list_ || !assistant_models_list_ || snapshot == assistant_preferences_snapshot_) return;
  assistant_preferences_snapshot_ = snapshot;
  BuildAssistantBackendCards(assistant_backends_list_, data);
  std::vector<std::string> providers;
  std::vector<std::u16string> provider_labels;
  if (const auto* backends = data.FindList("backends")) {
    for (const auto& backend : *backends) {
      const auto& entry = backend.GetDict();
      if (!entry.FindBool("enabled").value_or(false)) continue;
      providers.push_back(*entry.FindString("provider"));
      provider_labels.push_back(base::UTF8ToUTF16(*entry.FindString("label")));
    }
  }
  if (assistant_add_providers_ != providers) {
    assistant_add_providers_ = std::move(providers);
    ReplacePickerLabels(assistant_add_backend_, provider_labels);
    SyncPickerIndex(assistant_add_backend_,
                    provider_labels.empty() ? std::nullopt : std::optional<size_t>(0));
  }
  auto weak=weak_factory_.GetWeakPtr();
  const bool enabled=data.FindBool("enabled").value_or(false);
  auto text=[](const base::DictValue& d,const char* key){const auto* v=d.FindString(key);return v?base::UTF8ToUTF16(*v):std::u16string();};
  auto write=[](base::WeakPtr<WorkspaceShell> shell,base::DictValue command){if(shell&&shell->callbacks_.write_assistant)shell->callbacks_.write_assistant.Run(std::move(command));};
  assistant_models_list_->RemoveAllChildViews();
  if (data.FindBool("has_shortcut_access").value_or(false)) {
    auto* clear = PreferenceAction(assistant_models_list_, base::BindRepeating(
        [](decltype(write) write, base::WeakPtr<WorkspaceShell> shell, const ui::Event&) {
          write(shell, base::DictValue().Set("command", "clear_shortcut_access"));
        }, write, weak), T(u"Wyczyść zapamiętane zgody skrótów"));
    clear->SetEnabled(enabled);
  }
  const auto* default_model=data.FindString("default_model");
  const auto* models=data.FindList("models");
  {
    // One choice of the default model, above the list.
    auto* line=assistant_models_list_->AddChildView(std::make_unique<views::View>());
    auto* label=AddPreferenceCopy(line,T(u"Model domyślny"),kInk,0,static_cast<int>(gfx::Font::Weight::MEDIUM),false);
    std::vector<std::u16string> labels;std::vector<std::pair<std::string,std::string>> keys;size_t selected=0;
    for(size_t i=0;models&&i<models->size();++i){
      const auto& model=(*models)[i].GetDict();const std::string provider=*model.FindString("provider"),id=*model.FindString("id");
      if (!std::ranges::contains(assistant_add_providers_, provider)) continue;
      if(default_model&&*default_model==provider+"/"+id)selected=keys.size();
      labels.push_back(base::UTF8ToUTF16(id)+u" · "+text(model,"label"));keys.emplace_back(provider,id);
    }
    auto* picker=ChoicePicker(line,T(u"Model domyślny"),labels);
    SyncPickerIndex(picker,labels.empty()?std::nullopt:std::optional<size_t>(selected));picker->SetEnabled(enabled && !labels.empty());
    SetPickerCallback(picker,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,std::vector<std::pair<std::string,std::string>> keys,views::View* picker){
      const auto index=PickerIndex(picker);if(!index||*index>=keys.size())return;
      write(shell,base::DictValue().Set("command","default").Set("provider",keys[*index].first).Set("id",keys[*index].second));
    },write,weak,std::move(keys),base::Unretained(picker)));
    SetSidebarPanelLayout(line,false,gfx::Insets::TLBR(0,0,4,0),12,label,true);
  }
  std::vector<const base::DictValue*> grouped_models;
  if (models) {
    for (const auto& model : *models)
      grouped_models.push_back(&model.GetDict());
  }
  std::ranges::stable_sort(grouped_models, {}, [](const auto* model) {
    return *model->FindString("provider");
  });
  std::string previous_provider;
  for (const auto* entry : grouped_models) {
    const auto& model = *entry;
    const std::string provider=*model.FindString("provider"),id=*model.FindString("id");
    const bool provider_enabled = std::ranges::contains(assistant_add_providers_, provider);
    if (previous_provider != provider) {
      AddPreferenceCopy(assistant_models_list_,
                        text(model, "label") + (provider_enabled ? u"" : u" · " + T(u"Wyłączony")),
                        kMuted, -1, static_cast<int>(gfx::Font::Weight::SEMIBOLD), false);
      previous_provider = provider;
    }
    const bool is_default=provider_enabled&&default_model&&*default_model==provider+"/"+id;
    auto* line=assistant_models_list_->AddChildView(std::make_unique<views::View>());
    auto* labels=line->AddChildView(std::make_unique<views::View>());SetSidebarPanelLayout(labels,true,gfx::Insets(),2);
    AddPreferenceCopy(labels,base::UTF8ToUTF16(id)+(is_default?u" · "+T(u"domyślny"):u""),kInk,0,static_cast<int>(gfx::Font::Weight::MEDIUM),false);
    auto command=[&](const char* name){return base::DictValue().Set("command",name).Set("provider",provider).Set("id",id);};
    auto* toggle=PreferenceToggle(line,TF(u"Pokazuj {} w panelu",{base::UTF8ToUTF16(id)}));
    SetToggleOn(toggle,model.FindBool("visible").value_or(true));toggle->SetEnabled(enabled && provider_enabled && !is_default);
    SetActionCallback(toggle,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,const base::DictValue& c,views::View* toggle){
      write(shell,c.Clone().Set("visible",ToggleOn(toggle)));
    },write,weak,command("visible"),base::Unretained(toggle)));
    auto* remove=PreferenceAction(line,base::BindRepeating([](decltype(write) write,base::WeakPtr<WorkspaceShell> shell,const base::DictValue& c,const ui::Event&){write(shell,c.Clone());},write,weak,command("remove")),T(u"Usuń"));
    remove->GetViewAccessibility().SetName(TF(u"Usuń model {}",{base::UTF8ToUTF16(id)}));remove->SetEnabled(enabled&&models->size()>1);
    SetSidebarPanelLayout(line,false,gfx::Insets(),12,labels,true);
  }
  const bool can_add = enabled && !assistant_add_providers_.empty();
  assistant_add_backend_->SetEnabled(can_add && assistant_add_providers_.size() > 1);
  assistant_add_model_->view()->SetEnabled(can_add);
  assistant_add_button_->SetEnabled(can_add);
  RefreshChoiceViewports(assistant_backends_list_->parent());RefreshChoiceViewports(assistant_models_list_->parent());
  if(general_widget_)general_widget_->GetContentsView()->InvalidateLayout();
}
namespace {
void ShowAssistantDialog(views::Widget* owner, std::unique_ptr<ui::DialogModel> dialog) {
  auto* prompt = views::DialogDelegate::CreateDialogWidget(
      views::BubbleDialogModelHost::CreateModal(
          std::move(dialog), ui::mojom::ModalType::kWindow, /*autosize=*/false),
      owner->GetNativeWindow(), owner->GetNativeView());
  prompt->SetColorModeOverride(owner->color_mode_override());
  const auto area = display::Screen::Get()
                        ->GetDisplayNearestWindow(owner->GetNativeWindow())
                        .work_area();
  auto bounds = prompt->GetWindowBoundsInScreen();
  bounds.set_origin(owner->GetWindowBoundsInScreen().CenterPoint() -
                    gfx::Vector2d(bounds.width() / 2, bounds.height() / 2));
  bounds.AdjustToFit(area);
  prompt->SetBounds(bounds);
  prompt->Show();
}
}  // namespace

void WorkspaceShell::ShowAssistantKeyDialog(views::Widget* owner){
  if (!owner) owner = general_widget_.get();
  if (!owner) return;
  ui::DialogModel::Builder builder;auto* model=builder.model();
  auto dialog=builder.SetTitle(T(u"Połącz OpenAI"))
      .AddParagraph(ui::DialogModelLabel(T(u"Wklej klucz API ze swojego konta OpenAI. Zitter zapisze go w postaci zaszyfrowanej przy użyciu zabezpieczeń systemu.")))
      .AddPasswordField(kAssistantApiKeyField,T(u"Klucz API"),T(u"Klucz API OpenAI"),T(u"Wpisz klucz API"))
      .SetInitiallyFocusedField(kAssistantApiKeyField)
      .AddOkButton(base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell,ui::DialogModel* model){
        if(!shell)return true;
        const auto key=base::UTF16ToUTF8(base::TrimWhitespace(model->GetPasswordFieldByUniqueId(kAssistantApiKeyField)->text(),base::TRIM_ALL));
        if(key.empty()||key.size()>4096||key.find_first_of("\r\n")!=std::string::npos)return false;
        if(shell->callbacks_.write_assistant)shell->callbacks_.write_assistant.Run(base::DictValue().Set("command","save_key").Set("key",key));
        return true;
      },weak_factory_.GetWeakPtr(),base::Unretained(model)),ui::DialogModel::Button::Params().SetLabel(T(u"Zapisz klucz")))
      .AddCancelButton(base::DoNothing(),ui::DialogModel::Button::Params().SetLabel(T(u"Anuluj"))).Build();
  ShowAssistantDialog(owner, std::move(dialog));
}
void WorkspaceShell::ShowAssistantBackendInput(views::Widget* owner, std::string provider,
                                              std::u16string value) {
  if (!owner) return;
  const bool ollama = provider == "ollama";
  const auto label = ollama ? T(u"ID modelu") : T(u"Ścieżka do programu");
  const auto help = ollama
      ? T(u"Uruchom Ollama, pobierz model i wpisz jego pełną nazwę, np. qwen3:8b. Możesz też użyć przycisku „Wykryj modele”.")
      : provider == "codex"
          ? T(u"Uruchom codex login w terminalu i sprawdź codex login status. Jeśli wykrywanie nie działa, podaj pełną ścieżkę do natywnego codex.exe (lub codex na macOS i Linuksie). Puste pole włącza wykrywanie automatyczne.")
          : T(u"Uruchom claude w terminalu i zaloguj się poleceniem /login. Jeśli wykrywanie nie działa, podaj pełną ścieżkę do natywnego programu Claude Code. Puste pole włącza wykrywanie automatyczne.");
  ui::DialogModel::Builder builder;
  auto* model = builder.model();
  auto dialog = builder.SetTitle(AssistantProviderLabel(provider))
      .AddParagraph(ui::DialogModelLabel(help))
      .AddTextfield(kAssistantSetupField, label, ollama ? std::u16string() : value)
      .SetInitiallyFocusedField(kAssistantSetupField)
      .AddOkButton(base::BindRepeating([](base::WeakPtr<WorkspaceShell> shell, ui::DialogModel* model,
          std::string provider, bool ollama) {
        if (!shell || !shell->callbacks_.write_assistant) return true;
        const auto text = base::UTF16ToUTF8(base::TrimWhitespace(
            model->GetTextfieldByUniqueId(kAssistantSetupField)->text(), base::TRIM_ALL));
        if (ollama ? text.empty() || text.size() > 120
                   : !text.empty() && !base::FilePath::FromUTF8Unsafe(text).IsAbsolute()) return false;
        shell->callbacks_.write_assistant.Run(base::DictValue().Set("provider", provider)
            .Set("command", ollama ? "add" : "cli_path").Set(ollama ? "id" : "path", text));
        return true;
      }, weak_factory_.GetWeakPtr(), base::Unretained(model), provider, ollama),
      ui::DialogModel::Button::Params().SetLabel(T(u"Zapisz")))
      .AddCancelButton(base::DoNothing(), ui::DialogModel::Button::Params().SetLabel(T(u"Anuluj"))).Build();
  ShowAssistantDialog(owner, std::move(dialog));
}
void WorkspaceShell::OpenAssistantSettings() {
  OpenGeneralSettings();
  if (general_widget_ && general_widget_->IsVisible()) SelectPreferenceCategory(10);
}
void WorkspaceShell::OpenAdBlockingSettings() {
  OpenGeneralSettings();
  if (general_widget_ && general_widget_->IsVisible()) SelectPreferenceCategory(11);
}
void WorkspaceShell::RevealProfileFavorite(std::string_view id) {
  auto* row = pin_button(std::string(id));
  if (row) {
    ShowSidebar();
    sidebar_widget_->LayoutRootViewIfNecessary();
    row->ScrollViewToVisible();
    ScheduleMetalSidebar();
  }
  ShowToast(T(u"Dodano do ulubionych profilu"), {}, {});
}

void WorkspaceShell::OpenExtensionsSettings() {
  OpenGeneralSettings();
  if (general_widget_ && general_widget_->IsVisible())
    SelectPreferenceCategory(kExtensionsPreferenceCategory);
}
void WorkspaceShell::OpenPrivacySettings() {
  OpenGeneralSettings();
  SelectPreferenceCategory(2);
}
void WorkspaceShell::SelectPreferenceCategory(size_t category) {
  if (category >= preference_sections_.size()) return;
  if(preferences_form_){if(!preferences_form_->form->preference_select(category))return;}
  SyncPickerIndex(preferences_category_picker_,category);
  preferences_search_->SetText(u"");
  FilterPreferences();
}
void WorkspaceShell::FilterPreferences() {
  if (site_rules_list_) RefreshSitePreferences(false);
  const auto query = base::i18n::ToLower(base::TrimWhitespace(preferences_search_->GetText(), base::TRIM_ALL));
  if(!preferences_form_)return;
  SyncPickerIndex(preferences_category_picker_,preferences_form_->form->preference_current());
  std::vector<sidebar::PreferenceRow> rows;
  for(size_t i=0;i<preference_sections_.size();++i)for(const auto& row:preference_sections_[i].rows){sidebar::PreferenceRow input{};input.category=i;for(auto unit:row.keywords)input.keywords.push_back(unit);rows.push_back(std::move(input));}
  rust::Vec<uint16_t> normalized;for(auto unit:query)normalized.push_back(unit);
  auto visible=preferences_form_->form->preference_filter(std::move(normalized),rust::Slice<const sidebar::PreferenceRow>(rows.data(),rows.size()));
  size_t cursor=0;for(size_t i=0;i<preference_sections_.size();++i){auto& section=preference_sections_[i];for(auto& row:section.rows)row.view->SetVisible(visible.rows[cursor++]);section.view->SetVisible(visible.sections[i]);SetPreferenceNavigationSelected(section.navigation,visible.navigation[i]);}
  for(auto& group:preference_groups_)group.card->SetVisible(std::any_of(group.rows.begin(),group.rows.end(),[](const auto& row){return row->GetVisible();}));
  preferences_empty_->SetVisible(!visible.any);preferences_body_->InvalidateLayout();general_scroll_->ScrollTo(0);
}
void WorkspaceShell::SetBrowsingDataBusy(bool busy) {
  browsing_data_busy_ = busy;
  if (!clear_data_button_) return;
  clear_data_button_->SetEnabled(!busy);
  SetActionText(clear_data_button_,busy ? T(u"Czyszczenie…") : T(u"Wyczyść…"));
}
void WorkspaceShell::ReportPreferenceOutcome(int outcome, const std::string& key, bool ok, std::u16string native) {
  bool error = !ok;
  if (preferences_form_) {
    const auto status = preferences_form_->form->preference_outcome(sidebar::PreferenceOutcome{static_cast<uint8_t>(outcome)}, key, ok);
    native = base::UTF8ToUTF16(std::string(status.text)); error = status.error;
  }
  if (outcome != 4) { SetPreferencesStatus(std::move(native), error); return; }
  if (!general_status_) return;
  SetPanelText(general_status_, native); SetPreferenceCopyTone(general_status_, error ? kError : kMuted);
}
void WorkspaceShell::SetPreferencesStatus(std::u16string text, bool error) {
  if (!general_status_) return;
  SetPanelText(general_status_,text);SetPreferenceCopyTone(general_status_,error?kError:kMuted);
}
void WorkspaceShell::PreferenceTextEdited(const std::string& key){
  if(preferences_form_){preferences_form_->form->preference_edited(key);return;}
  preference_text_dirty_.insert(key);
}
void WorkspaceShell::PreferenceTextSaved(const std::string& key,bool ok){
  if(preferences_form_){preferences_form_->form->preference_saved(key,ok);return;}
  if(ok)preference_text_dirty_.erase(key);
}
bool WorkspaceShell::SyncPreferenceText(const std::string& key,bool present,bool editable,bool composing,bool profile_changed){
  if(preferences_form_)return preferences_form_->form->preference_sync_text(key,present,editable,composing,profile_changed);
  const bool replace=present&&((!preference_text_dirty_.contains(key)&&!composing)||!editable||profile_changed);
  if(replace)preference_text_dirty_.erase(key);return replace;
}
void WorkspaceShell::ResetPreferenceRuleLimit(){
  if(preferences_form_){preferences_form_->form->preference_reset_rules();return;}
  site_rules_limit_=50;
}
void WorkspaceShell::MorePreferenceRules(){
  if(preferences_form_){preferences_form_->form->preference_more_rules();return;}
  site_rules_limit_+=50;
}
size_t WorkspaceShell::PreferenceRuleLimit() const{
  if(preferences_form_)return preferences_form_->form->preference_rule_limit();
  return site_rules_limit_;
}
void WorkspaceShell::SaveTextPreference(std::string key) {
  auto it = preference_textfields_.find(key);
  if (it == preference_textfields_.end()) return;
  const bool enabled=it->second->view()->GetEnabledInViewsSubtree();
  const bool composing=it->second->IsIMEComposing();
  if(preferences_form_){if(!preferences_form_->form->preference_can_save(enabled,composing))return;}
  const bool ok = callbacks_.write_text_preference && callbacks_.write_text_preference.Run(key, base::UTF16ToUTF8(it->second->GetText()));
  PreferenceTextSaved(key,ok);
  RefreshGeneralControls();
  ReportPreferenceOutcome(0, key, ok, ok ? T(u"Zapisano. Witryna może wymagać odświeżenia, aby zastosować zmianę.") :
      key == "accept_languages" ? T(u"Podaj poprawne kody języków oddzielone przecinkami, np. pl, en-US, en.") :
      key == "dns_templates" ? T(u"Podaj poprawny szablon DNS-over-HTTPS. W trybie ścisłym adres nie może być pusty.") :
      T(u"Nie udało się zapisać. Podaj nazwę rodziny czcionki (do 128 znaków). Ustawienie może być zarządzane."));
}
void WorkspaceShell::SaveSitePreference() {
  if(!site_origin_||site_origin_->IsIMEComposing())return;
  const auto type = PickerIndex(site_type_).value_or(kSitePreferenceKeys.size());
  const auto policy = PickerIndex(site_policy_).value_or(0);
  if (type >= kSitePreferenceKeys.size()) return;
  const bool ok = callbacks_.write_site_preference && callbacks_.write_site_preference.Run(
      base::UTF16ToUTF8(site_origin_->GetText()), kSitePreferenceKeys[type], static_cast<int>(policy));
  if (ok) { RefreshSitePreferences(); FilterPreferences(); }
  ReportPreferenceOutcome(1, "", ok, ok ? T(u"Zapisano wyjątek w tym profilu. Odśwież witrynę, aby zastosować zmianę.") :
      T(u"Nie zapisano wyjątku. Podaj adres HTTP(S) bez ścieżki i danych logowania. Sprawdź wybraną politykę; reguły zarządzane nie mogą być zmieniane."));
}
void WorkspaceShell::PostRemoveSiteRule(SitePreferenceRule rule,std::string profile_id){
  // Retain the click's exact backend value and profile through the deferred task.
  base::SingleThreadTaskRunner::GetCurrentDefault()->PostTask(FROM_HERE,base::BindOnce([](base::WeakPtr<WorkspaceShell> shell,SitePreferenceRule rule,std::string profile_id){if(!shell||shell->state_.profile_id!=profile_id)return;const bool ok=shell->callbacks_.remove_site_preference&&shell->callbacks_.remove_site_preference.Run(std::move(rule));shell->RefreshSitePreferences();shell->FilterPreferences();shell->ReportPreferenceOutcome(2,"",ok,ok?T(u"Usunięto wyjątek. Witryna wróci do ustawień domyślnych."):T(u"Nie udało się usunąć wyjątku. Reguła może być zarządzana."));},weak_factory_.GetWeakPtr(),std::move(rule),std::move(profile_id)));
}
